function bewegeSchlaeger(x, taste) {
  let neueX = x;
  if (taste === 'ArrowLeft') neueX -= 20;
  if (taste === 'ArrowRight') neueX += 20;
  if (neueX < 0) neueX = 0;
  if (neueX > 320) neueX = 320;
  return neueX;
}

console.log(bewegeSchlaeger(0, 'ArrowLeft'));

